// SYNTHETIC workout track for previews and browser checks: an invented run in the same fictional
// region as tests/fit_factory.py (around 0° N 0° E, open sea, inside the ±1° box the publication
// check allows). Generated by formula; no device, place or person behind any value. The response
// has the shape of GET /api/dashboard/workouts/{id}/track (docs/reference/garmin-tracks.md).
const STEP = 4; // seconds between records, like a watch's smart recording
const PAUSE = [1264, 1324]; // one timer pause of a minute
const LAP = 2000; // metres per lap
const round = (value, digits) => (value == null ? null : Number(value.toFixed(digits)));
const wave = (i, seed) => (Math.sin(i * 0.071 + seed) + Math.sin(i * 0.023 + seed * 1.7)) / 2;

// A wobbly loop around a point a little north-east of 0°/0°.
function position(share) {
  const angle = (0.03 + share * 0.93) * 2 * Math.PI; // not closed: start and finish stay apart
  const radius = 0.0068 * (1 + 0.22 * Math.sin(3 * angle) + 0.08 * Math.cos(5 * angle));
  return [0.0021 + radius * Math.sin(angle), 0.0034 + 1.25 * radius * Math.cos(angle)];
}

function records(seconds, withPositions) {
  const out = [];
  let distance = 0, time = 0;
  for (let i = 0; time <= seconds; i++, time += STEP) {
    if (time > PAUSE[0] && time < PAUSE[1]) continue;
    const speed = 2.62 + 0.4 * wave(i, 1) + (i % 97 === 50 ? 0.5 : 0);
    if (out.length) distance += speed * STEP;
    out.push({ time, speed, distance, heart_rate: Math.round(128 + 22 * Math.min(1, i / 120) + 9 * wave(i, 4)),
      altitude: 38 + 11 * Math.sin(i * 0.009) + 3 * wave(i, 7) });
  }
  const total = out[out.length - 1].distance;
  for (const [i, row] of out.entries()) {
    // A short gap in the satellite fix cuts the line once.
    const fix = withPositions && !(i >= 300 && i < 304);
    [row.latitude, row.longitude] = fix ? position(row.distance / total) : [null, null];
  }
  return out;
}

function laps(rows) {
  const columns = { start_time: [], time: [], elapsed_seconds: [], moving_seconds: [], distance: [], average_speed: [],
    maximum_speed: [], average_heart_rate: [], maximum_heart_rate: [], start_index: [], end_index: [] };
  let start = 0;
  for (let i = 1; i <= rows.length; i++) {
    const last = i === rows.length;
    if (!last && Math.floor(rows[i].distance / LAP) === Math.floor(rows[start].distance / LAP)) continue;
    const part = rows.slice(start, i), first = part[0], end = part[part.length - 1];
    const elapsed = end.time - first.time, paused = first.time < PAUSE[0] && end.time > PAUSE[1] ? PAUSE[1] - PAUSE[0] : 0;
    const values = { start_time: first.time, time: end.time, elapsed_seconds: elapsed, moving_seconds: elapsed - paused,
      distance: round(end.distance - first.distance, 1), average_speed: round((end.distance - first.distance) / (elapsed - paused), 3),
      maximum_speed: round(Math.max(...part.map(row => row.speed)), 3),
      average_heart_rate: Math.round(part.reduce((sum, row) => sum + row.heart_rate, 0) / part.length),
      maximum_heart_rate: Math.max(...part.map(row => row.heart_rate)), start_index: start, end_index: i - 1 };
    for (const [key, value] of Object.entries(values)) columns[key].push(value);
    start = i;
  }
  return columns;
}

function climb(rows, sign) {
  let sum = 0;
  for (let i = 1; i < rows.length; i++) sum += Math.max(0, sign * (rows[i].altitude - rows[i - 1].altitude));
  return round(sum, 1);
}

function summary(rows, start) {
  const last = rows[rows.length - 1], moving = last.time - (PAUSE[1] - PAUSE[0]);
  const placed = rows.filter(row => row.latitude != null);
  const bounds = placed.length ? [Math.min(...placed.map(row => row.latitude)), Math.min(...placed.map(row => row.longitude)),
    Math.max(...placed.map(row => row.latitude)), Math.max(...placed.map(row => row.longitude))].map(value => round(value, 7)) : null;
  return { start_time: start, elapsed_seconds: last.time, moving_seconds: moving, distance: round(last.distance, 1),
    average_speed: round(last.distance / moving, 3), maximum_speed: round(Math.max(...rows.map(row => row.speed)), 3),
    ascent: climb(rows, 1), descent: climb(rows, -1), bounds };
}

/** The track response for one workout id; `withPositions: false` is an indoor (treadmill) track. */
function workoutTrack(id, { withPositions = true, seconds = 2640, type = 'RUNNING', start = '2026-10-11T09:15:00Z' } = {}) {
  const rows = records(seconds, withPositions);
  const column = key => rows.map(row => round(row[key], key === 'latitude' || key === 'longitude' ? 7 : 3));
  const samples = { time: rows.map(row => row.time) };
  for (const key of ['latitude', 'longitude', 'altitude', 'speed', 'heart_rate', 'distance'])
    if (withPositions || !['latitude', 'longitude'].includes(key)) samples[key] = column(key);
  return { track: { workout_id: id, exercise_type: type, method_version: 1, summary: summary(rows, start),
    source_point_count: rows.length, point_count: rows.length, samples, laps: laps(rows),
    events: { time: [PAUSE[0], PAUSE[1]], action: ['pause', 'resume'] } } };
}

module.exports = { workoutTrack };
